    "faq.h2": "Questions fréquentes",
    "faq.q1": "Mon code de stratégie est-il partagé ou stocké ?",
    "faq.a1": "Non. Votre code sert au calcul de l'audit et n'est jamais publié ni revendu. Vous gardez la propriété de votre stratégie.",
    "faq.q2": "Quels formats puis-je déposer ?",
    "faq.a2": "Pine Script, scripts Python, notebooks ou un dossier compatible. Vous pouvez aussi fournir vos trades exportés.",
    "faq.q3": "Les chiffres du site sont-ils des résultats clients ?",
    "faq.a3": "Non. Toutes les données affichées ici sont des exemples illustratifs. Un audit ne garantit aucune performance future.",
    "faq.q4": "Comment se débloque le rapport ?",
    "faq.a4": "Après paiement, votre demande passe une validation humaine avant que le rapport complet ne soit accessible, via un lien temporaire.",
    "faq.q5": "Comment l'audit détecte-t-il le look-ahead bias et la sur-optimisation ?",
    "faq.a5": "Le moteur recalcule chaque métrique hors échantillon (walk-forward 70/30), rejoue les trades sur les bougies réelles et compare le résultat déclaré au résultat recalculé. Le look-ahead (information utilisée avant la clôture de la bougie), les frais omis et la fenêtre unique de sur-optimisation sont signalés comme divergences.",
    "faq.q6": "Comment est calculé le score de robustesse ?",
    "faq.a6": "Le score (0-100) pondère la stabilité hors échantillon (40%), le Profit Factor net (>1.5 = 30%), le drawdown (<20% = 20%) et le nombre de trades (>100 = 10%). Un badge vert n'est délivré que si le verdict du moteur est CERTIFIED (score ≥ 70).",
    "faq.q7": "Qu'est-ce que la certification d'un backtest garantit ?",
    "faq.a7": "La certification atteste que les métriques déclarées ont été recalculées et scellées par un tiers indépendant, avec détection des biais. Elle ne garantit pas un rendement futur ni l'absence de perte. Chaque badge est lié à un hash SHA256 immuable du code audité.",
    "faq.q8": "Mon code source est-il partagé ou conservé ?",
    "faq.a8": "Non. Votre code alimente le calcul d'audit en lecture seule et n'est jamais publié, revendu ni exécuté avec des ordres réels. L'analyse est statique ; les fichiers opérationnels sont supprimés selon la politique de conservation, seules les empreintes et preuves de commande sont gardées.",
    "faq.q9": "Comment fonctionnent les abonnements et l'accès au Scan live ?",
    "faq.a9": "L'audit est un paiement unique (aucun renouvellement automatique). Le Scan live récurrent est sur invitation pendant la bêta ; aucun abonnement ne peut être débité avant validation. L'accès au rapport livré est temporaire et lié à votre commande.",
