    "legal.status": "Test beta · no real payment",
    "legal.meta": "Bundle beta-fr-2026-08-12-v1 · published 12 August 2026",
    "legal.nav": "Legal documents",
    "legal.translationNotice": "The French version is the controlling contractual text. Other languages are provided for information until native legal review.",
    "legal.refunds": "Withdrawal",
    "legal.terms.title": "Beta terms",
    "legal.terms.lead": "These terms govern BacktestProof testing. They are not yet the final commercial terms for a public service.",
    "legal.terms.warning": "The service currently uses Stripe test mode. No real payment may be accepted before the pending RNE filing, inbound contact, consumer mediator and final delivery times are validated.",
    "legal.terms.s1h": "1. Beta operator",
    "legal.terms.s1p": "Mathieu Sarrue, sole trader · declared trade name: Prism Works · SIREN 903 756 575 · SIRET 903 756 575 00028 · 11 avenue du Huit Mai, 13400 Aubagne, France. Product: StratVerity / BacktestProof. The public update of the trade name and SaaS activity is being processed by the French one-stop shop.",
    "legal.terms.vat": "VAT not applicable — Article 293 B of the French Tax Code.",
    "legal.terms.s2h": "2. Service under test",
    "legal.terms.s2p": "BacktestProof receives a supported Pine or Python strategy or folder, first checks safety and compatibility, then prepares its audit. A score or report guarantees neither future returns nor absence of loss. Live Scan remains invitation-only and is not activated by public payment.",
    "legal.terms.s3h": "3. Order and evidence",
    "legal.terms.s3p": "Scope, price, document version and fingerprint are calculated server-side. Acceptance is timestamped and stored in an immutable order-linked register. A signed Stripe webhook confirms payment; it never starts client code directly.",
    "legal.terms.s4h": "4. Responsibilities",
    "legal.terms.s4p": "The client warrants that they may submit the files and data. They remain solely responsible for trading decisions. StratVerity may reject or isolate dangerous, illegal or incompatible content.",
    "legal.terms.s5h": "5. Support and disputes",
    "legal.terms.s5p": "The planned address is support@stratverity.com. It will only be presented as a support channel after message receipt is validated. Applicable law and mediation arrangements will be published before real payments. Their absence automatically keeps the live launch at NO-GO.",
    "legal.privacy.title": "Privacy",
    "legal.privacy.lead": "We limit collected data to what is needed to qualify, audit, deliver and secure the service.",
    "legal.privacy.s1h": "Data and purposes",
    "legal.privacy.s1p": "We may process delivery email, order information, file fingerprints, uploaded files, technical results and security logs to provide the service, preserve contractual evidence, prevent fraud, support users and improve the product.",
    "legal.privacy.s2h": "Recipients and hosting",
    "legal.privacy.s2p": "Planned providers include Stripe for payment and AWS for hosting and email. No client code is published, sold or added to a marketplace in this beta. Any transfer outside the EEA must rely on the relevant provider safeguards.",
    "legal.privacy.s3h": "Retention, rights and contact",
    "legal.privacy.s3p": "The controller is Mathieu Sarrue, sole trader, 11 avenue du Huit Mai, 13400 Aubagne, France (SIRET 903 756 575 00028). The planned rights address is support@stratverity.com; receipt testing is still required before launch. Exact retention periods will be published before launch. No real payment may be enabled until validation.",
    "legal.license.title": "Content licence",
    "legal.license.lead": "You remain the owner of your strategy. The beta licence is limited to providing the service and grants no resale right.",
    "legal.license.s1h": "Rights granted",
    "legal.license.s1p": "For the time required for service, evidence and security, the client authorises StratVerity to host, technically copy, analyse and test submitted content to qualify the request, perform the audit, deliver the result and handle incidents. Aggregated or de-identified learnings may improve detection methods.",
    "legal.license.s2h": "Rights not granted",
    "legal.license.s2p": "This version expressly excludes publishing, distributing, selling, sublicensing or integrating identifiable client code into a strategy or marketplace. Any future change would require separate, clear, limited and legally validated terms.",
    "legal.license.s3h": "Deletion and evidence",
    "legal.license.s3p": "Operational files will be deleted under the published retention policy. Fingerprints, order evidence and records required for security or legal obligations may be retained separately for the applicable period.",
    "legal.refunds.title": "Withdrawal and refunds",
    "legal.refunds.lead": "The immediate-start request is recorded separately from payment confirmation and does not remove mandatory customer rights.",
    "legal.refunds.warning": "Delivery timing, refund terms and handling of consumers outside France must be finalised with seller status before any real payment.",
    "legal.refunds.s1h": "Requested start",
    "legal.refunds.s1p": "When moving to Stripe, the client explicitly requests qualification to start after payment confirmation and acknowledges receipt of withdrawal information. This acknowledgement is linked to the order and timestamped server-side.",
    "legal.refunds.s2h": "Incident or impossibility",
    "legal.refunds.s2p": "A strategy rejected before execution, duplicate payment or service-caused impossibility must enter human review. A disappointing trading result does not automatically deny a refund; each request depends on the service actually provided and mandatory rules.",
    "legal.risk.title": "Risk warning",
    "legal.risk.lead": "A backtest is a historical measurement under assumptions. It is neither a promise of profit nor investment advice.",
    "legal.risk.s1h": "Backtest limitations",
    "legal.risk.s1p": "Data, fees, spreads, slippage, liquidity, latency, selection bias, overfitting and code errors can change results. Past performance does not predict future performance and total loss of committed capital remains possible.",
    "legal.risk.s2h": "Audit scope",
