    "faq.h2": "Частые вопросы",
    "faq.q1": "Передаётся ли или хранится код моей стратегии?",
    "faq.a1": "Нет. Ваш код используется для расчёта аудита и никогда не публикуется и не перепродаётся. Право на стратегию остаётся за вами.",
    "faq.q2": "Какие форматы можно загрузить?",
    "faq.a2": "Pine Script, скрипты Python, notebooks или совместимую папку. Также можно предоставить экспортированные сделки.",
    "faq.q3": "Цифры на сайте — это реальные результаты клиентов?",
