    "faq.q5": "How does the audit detect look-ahead bias and overfitting?",
    "faq.a5": "The engine recomputes every metric out-of-sample (70/30 walk-forward), replays trades on real candles and compares the declared result against the recomputed one. Look-ahead (info used before bar close), missing fees and single-window overfitting are flagged as divergences.",
    "faq.q6": "How is the robustness score calculated?",
    "faq.a6": "The score (0-100) weights out-of-sample stability (40%), net Profit Factor (>1.5 = 30%), drawdown (<20% = 20%) and trade count (>100 = 10%). A green badge is issued only when the engine verdict is CERTIFIED (score ≥ 70).",
    "faq.q7": "What does backtest certification guarantee?",
    "faq.a7": "Certification attests that declared metrics were recomputed and sealed by an independent third party, with bias detection. It guarantees neither future returns nor absence of loss. Each badge is tied to an immutable SHA256 hash of the audited code.",
    "faq.q8": "Is my source code shared or stored?",
    "faq.a8": "No. Your code powers read-only audit computation and is never published, resold or executed with real orders. Analysis is static; operational files are deleted under the retention policy, only fingerprints and order evidence are kept.",
    "faq.q9": "How do subscriptions and Live Scan access work?",
    "faq.a9": "The audit is a one-time payment (no auto-renewal). The recurring Live Scan is invitation-only during beta; no subscription can be charged before validation. Access to a delivered report is temporary and tied to your order.",
