    "legal.terms.s2h": "2. Service under test",
    "legal.terms.s2p": "BacktestProof receives a supported Pine or Python strategy or folder, first checks safety and compatibility, then prepares its audit. A score or report guarantees neither future returns nor absence of loss. Live Scan remains invitation-only and is not activated by public payment.",
    "legal.terms.s3h": "3. Order and evidence",
    "legal.terms.s3p": "Scope, price, document version and fingerprint are calculated server-side. Acceptance is timestamped and stored in an immutable order-linked register. A signed Stripe webhook confirms payment; it never starts client code directly.",
    "legal.terms.s4h": "4. Responsibilities",
    "legal.terms.s4p": "The client warrants that they may submit the files and data. They remain solely responsible for trading decisions. StratVerity may reject or isolate dangerous, illegal or incompatible content.",
    "legal.terms.s5h": "5. Support and disputes",
    "legal.terms.s5p": "The planned address is support@stratverity.com. It will only be presented as a support channel after message receipt is validated. Applicable law and mediation arrangements will be published before real payments. Their absence automatically keeps the live launch at NO-GO.",
    "legal.privacy.title": "Privacy",
