    "legal.privacy.s2h": "Recipients and hosting",
    "legal.privacy.s2p": "Planned providers include Stripe for payment and AWS for hosting and email. No client code is published, sold or added to a marketplace in this beta. Any transfer outside the EEA must rely on the relevant provider safeguards.",
    "legal.privacy.s3h": "Retention, rights and contact",
    "legal.privacy.s3p": "The controller is Mathieu Sarrue, sole trader, 11 avenue du Huit Mai, 13400 Aubagne, France (SIRET 903 756 575 00028). The planned rights address is support@stratverity.com; receipt testing is still required before launch. Exact retention periods will be published before launch. No real payment may be enabled until validation.",
    "legal.license.title": "Content licence",
