    "legal.risk.title": "Risk warning",
    "legal.risk.lead": "A backtest is a historical measurement under assumptions. It is neither a promise of profit nor investment advice.",
    "legal.risk.s1h": "Backtest limitations",
    "legal.risk.s1p": "Data, fees, spreads, slippage, liquidity, latency, selection bias, overfitting and code errors can change results. Past performance does not predict future performance and total loss of committed capital remains possible.",
